// The Morada data used in the scenarios: the month's charges and notices.
// Everything is generated by deterministic SQL, so the output is always the same.
import type pg from "pg";

export async function prepare(db: pg.Client): Promise<void> {
  await db.query(`
    DROP SCHEMA IF EXISTS billing CASCADE;
    DROP SCHEMA IF EXISTS communications CASCADE;
    CREATE SCHEMA billing;
    CREATE SCHEMA communications;
    CREATE TABLE billing.charges (
      id integer PRIMARY KEY,
      community integer NOT NULL,
      unit integer NOT NULL,
      due_date date NOT NULL,
      amount_cents integer NOT NULL,
      paid_on date
    );
    INSERT INTO billing.charges
      SELECT i, (i - 1) / 100 + 1, (i - 1) % 100 + 1, date '2026-11-05',
             45000 + (i * 37) % 30000, NULL
      FROM generate_series(1, 3000) AS i;
    CREATE TABLE communications.notices (
      id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
      community integer NOT NULL,
      text text NOT NULL
    );`);
  await publishNotices(db, 100);
}

// Each payment is its own transaction, as in the app
export async function pay(db: pg.Client, count: number): Promise<void> {
  for (let i = 0; i < count; i++) {
    await db.query(`
      UPDATE billing.charges SET paid_on = date '2026-11-05'
      WHERE id = (SELECT min(id) FROM billing.charges WHERE paid_on IS NULL)`);
  }
}

export async function publishNotices(db: pg.Client, count: number): Promise<void> {
  for (let i = 0; i < count; i++) {
    await db.query(
      "INSERT INTO communications.notices (community, text) VALUES ($1, $2)",
      [(i % 30) + 1, `Notice ${i + 1}: water pump maintenance`],
    );
  }
}

// A summary that changes if any charge changes: how many, how many paid, the
// amounts, and a hash of every row in order
export async function signature(db: pg.Client): Promise<string> {
  const { rows } = await db.query(`
    SELECT count(*)::int AS total, count(paid_on)::int AS paid,
           md5(string_agg(id || ':' || amount_cents || ':' ||
                          coalesce(paid_on::text, '-'), ',' ORDER BY id)) AS hash
    FROM billing.charges`);
  const r = rows[0];
  return `${r.total} charges, ${r.paid} paid, hash ${r.hash.slice(0, 12)}`;
}

export async function countNotices(db: pg.Client): Promise<number> {
  const { rows } = await db.query(
    "SELECT count(*)::int AS n FROM communications.notices",
  );
  return rows[0].n;
}

export async function countPaid(db: pg.Client): Promise<number> {
  const { rows } = await db.query(
    "SELECT count(paid_on)::int AS n FROM billing.charges",
  );
  return rows[0].n;
}
